=== FILE: tb/repro_data_byte.v ===
`timescale 1ns / 1ps
// Repro A (data_byte_fail): data bits must go out least significant bit first.
module tb_uart_repro;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;
    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer i;
    reg [10:0] bits;
    reg [7:0]  bytes [0:3];

    uart_frame_tx #(.CLKS_PER_BIT(4)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    // bits[0] = start bit, bits[1..8] = data bits LSB first, bits[9] = parity, bits[10] = stop
    task send_and_sample(input [7:0] b, output [10:0] s);
        integer k;
        begin
            @(negedge clk); data = b; start = 1'b1;
            @(negedge clk); start = 1'b0;
            @(negedge clk); @(negedge clk);
            s[0] = tx;
            for (k = 1; k < 11; k = k + 1) begin
                repeat (4) @(negedge clk);
                s[k] = tx;
            end
            wait (!busy);
            repeat (4) @(negedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        bytes[0] = 8'h01; bytes[1] = 8'h80; bytes[2] = 8'hC5; bytes[3] = 8'h12;
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        for (i = 0; i < 4; i = i + 1) begin
            send_and_sample(bytes[i], bits);
            if (bits[8:1] === bytes[i]) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK data_byte: sent %h, received %h", bytes[i], bits[8:1]);
            end
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #100000;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end
endmodule
=== END FILE ===

