// Repro C (frame_period_fail): a frame is 11 bit periods; busy must last 11*CLKS_PER_BIT clocks.
module tb_uart_repro;
    localparam integer CPB = 4;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;
    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer i;
    integer cnt;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        for (i = 0; i < 2; i = i + 1) begin
            @(negedge clk); data = (i == 0) ? 8'h55 : 8'h0F; start = 1'b1;
            @(negedge clk); start = 1'b0;
            cnt = 0;
            while (busy && cnt < 1000) begin
                cnt = cnt + 1;
                @(negedge clk);
            end
            if (cnt == 11 * CPB) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK frame_period: busy lasted %0d clocks, expected %0d", cnt, 11 * CPB);
            end
            repeat (4) @(negedge clk);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #100000;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end
endmodule
